/**
 * Seller identity-verification uploads (student ID image + short video).
 *
 * Files land in the PRIVATE `verification-documents` bucket, namespaced under
 * `{userId}/` so Storage RLS scopes access to the owner (and to admins via the
 * service-role client). Because the bucket is private there are no public URLs;
 * the stored value is the object *path*, and administrators view the file with
 * a signed URL generated by the admin API route.
 *
 * Enforces per-file type and size:
 *   - ID image: JPG/PNG/WEBP up to 10MB (phone cameras commonly exceed 1MB).
 *   - Video:    MP4/WEBM/MOV up to 25MB (short in-app recording).
 * Files are deleted after an admin reviews the verification, so a generous
 * per-file ceiling is safe while still blocking accidental huge uploads. The
 * `verification-documents` bucket must allow the same size in Supabase Storage.
 * The "about 3 seconds" requirement is validated in the UI by reading the
 * `<video>` metadata length before upload (this util only guards size/type).
 */
const MAX_IMAGE_BYTES = 10 * 1024 * 1024; // 10MB
const MAX_VIDEO_BYTES = 25 * 1024 * 1024; // 25MB
const ALLOWED_IMAGE = ['image/jpeg', 'image/png', 'image/webp'];
const ALLOWED_VIDEO = ['video/mp4', 'video/webm', 'video/quicktime'];
const BUCKET = 'verification-documents';

import type { SupabaseClient } from '@supabase/supabase-js';

type StorageClient = Pick<SupabaseClient, 'storage'>;

type UploadResult = { ok: true; path: string } | { ok: false; error: string };

function extFor(file: File): string {
  return file.name.split('.').pop()?.toLowerCase() || 'bin';
}

/** `video/webm;codecs=opus` → `video/webm`. Blob types often carry parameters. */
function baseType(file: File): string {
  return (file.type || '').split(';')[0].trim().toLowerCase();
}

/**
 * Turn a Supabase Storage error into something the seller can act on. The most
 * common causes are a bucket-level size limit (separate from MAX_*_BYTES), a
 * missing/denied storage policy, or an unsupported MIME type; the raw message
 * is appended so support can diagnose anything else.
 */
function storageErrorMessage(
  error: { message?: string } | null,
  label: 'ID card' | 'verification video',
): string {
  const raw = error?.message || '';
  const lower = raw.toLowerCase();

  if (
    lower.includes('maximum allowed size') ||
    lower.includes('too large') ||
    lower.includes('exceeded') ||
    lower.includes('payload')
  ) {
    return `Your ${label} is larger than the verification storage allows. Ask an administrator to raise the verification-documents bucket size limit.`;
  }
  if (
    lower.includes('row-level security') ||
    lower.includes('not authorized') ||
    lower.includes('unauthorized') ||
    lower.includes('permission')
  ) {
    return `Storage rejected your ${label} upload (permission denied). Sign out, sign in again, and retry.`;
  }
  if (lower.includes('bucket not found')) {
    return 'Verification storage is not configured yet. Please contact support.';
  }
  if (lower.includes('mime') || lower.includes('content type')) {
    return `This ${label} file type is not allowed by storage. Use JPG, PNG or WEBP for the ID card.`;
  }
  return `Could not upload your ${label}${raw ? `: ${raw}` : '. Please try again.'}`;
}

/** Upload the student ID card image. Returns the object path, not a public URL. */
export async function uploadStudentId(
  supabase: StorageClient,
  userId: string,
  file: File | null,
): Promise<UploadResult> {
  if (!file) return { ok: true, path: '' };
  if (!ALLOWED_IMAGE.includes(baseType(file))) {
    return { ok: false, error: 'Only JPG, PNG or WEBP images are allowed for your ID card.' };
  }
  if (file.size > MAX_IMAGE_BYTES) {
    return { ok: false, error: 'ID card image must be 10MB or smaller.' };
  }
  const path = `${userId}/student-id_${Date.now()}.${extFor(file)}`;
  const { data, error } = await supabase.storage.from(BUCKET).upload(path, file, {
    upsert: true,
  });
  if (error || !data?.path) {
    console.error('[verify] id upload failed', error);
    return { ok: false, error: storageErrorMessage(error, 'ID card') };
  }
  return { ok: true, path: data.path };
}

/** Upload the 3-second verification selfie video. Returns the object path. */
export async function uploadVerificationVideo(
  supabase: StorageClient,
  userId: string,
  file: File | null,
): Promise<UploadResult> {
  if (!file) return { ok: true, path: '' };
  if (!ALLOWED_VIDEO.includes(baseType(file))) {
    return { ok: false, error: 'Only MP4, WEBM or MOV videos are allowed.' };
  }
  if (file.size > MAX_VIDEO_BYTES) {
    return { ok: false, error: 'Verification video must be 25MB or smaller. Keep it short.' };
  }
  const path = `${userId}/verification-video_${Date.now()}.${extFor(file)}`;
  const { data, error } = await supabase.storage.from(BUCKET).upload(path, file, {
    upsert: true,
  });
  if (error || !data?.path) {
    console.error('[verify] video upload failed', error);
    return { ok: false, error: storageErrorMessage(error, 'verification video') };
  }
  return { ok: true, path: data.path };
}